    description: "Quß║ún l├╜ c├íc mß╗æc ─æiß╗âm v├á ─æß║╖c quyß╗ün th├ánh vi├¬n",
};

export default function MembershipTierPage() {
    return <MembershipTierManagement />;
}

import { Metadata } from "next";
import InventoryManagement from "@/components/features/admin/inventory/InventoryManagement";

export const metadata: Metadata = {
    title: "Quß║ún l├╜ Nhß║¡p kho | Th╞░ Viß╗çn",
    description: "Nhß║¡p s├ích mß╗¢i v├áo kho",
};

export default function InventoryPage() {
    return <InventoryManagement />;
}

import { Metadata } from "next";
import SessionManagement from "@/components/features/admin/session/SessionManagement";

export const metadata: Metadata = {
    title: "Quß║ún l├╜ Phi├¬n | Th╞░ Viß╗çn",
    description: "Quß║ún l├╜ thiß║┐t bß╗ï ─æ─âng nhß║¡p",
};

export default function SessionPage() {
    return <SessionManagement />;
}

import { Metadata } from "next";
import PaymentManagement from "@/components/features/admin/payment/PaymentManagement";

export const metadata: Metadata = {
    title: "─Éß╗æi so├ít thanh to├ín | Th╞░ Viß╗çn",
