"use client";

import { useEffect, useState } from "react";
import { Plus, Pencil, Trash2, CheckCircle2, XCircle, LayoutDashboard } from "lucide-react";
import { toast } from "sonner";
import { AdminBanner, getAdminBanners, createAdminBanner, updateAdminBanner, deleteAdminBanner } from "@/services/adminBanner";

export default function BannerManagement() {
    const [banners, setBanners] = useState<AdminBanner[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingBanner, setEditingBanner] = useState<AdminBanner | null>(null);
    
    const [form, setForm] = useState({
        title: "",
        description: "",
        imageUrl: "",
        linkUrl: "",
        displayOrder: 0,
        isActive: true,
    });

    useEffect(() => {
        fetchBanners();
    }, []);

    const fetchBanners = async () => {
        setIsLoading(true);
        try {
            const res = await getAdminBanners();
            if (res.success && res.data) {
                setBanners(res.data);
            } else {
                toast.error(res.message || "Lß╗ùi tß║úi dß╗» liß╗çu banner");
            }
        } catch (error) {
            toast.error("Lß╗ùi kß║┐t nß╗æi khi tß║úi banner");
        } finally {
            setIsLoading(false);
        }
    };

    const handleOpenModal = (banner?: AdminBanner) => {
        if (banner) {
            setEditingBanner(banner);
            setForm({
                title: banner.title,
                description: banner.description || "",
                imageUrl: banner.imageUrl,
                linkUrl: banner.linkUrl || "",
                displayOrder: banner.displayOrder,
                isActive: banner.isActive,
            });
        } else {
            setEditingBanner(null);
            setForm({
                title: "",
                description: "",
                imageUrl: "",
                linkUrl: "",
                displayOrder: 0,
                isActive: true,
            });
        }
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingBanner(null);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            if (editingBanner) {
                const res = await updateAdminBanner(editingBanner.id, form);
                if (res.success) {
                    toast.success("Cß║¡p nhß║¡t th├ánh c├┤ng!");
                    fetchBanners();
                    handleCloseModal();
                } else {
                    toast.error(res.message);
                }
            } else {
                const res = await createAdminBanner(form);
                if (res.success) {
                    toast.success("Th├¬m mß╗¢i th├ánh c├┤ng!");
                    fetchBanners();
                    handleCloseModal();
                } else {
                    toast.error(res.message);
                }
            }
        } catch (error) {
            toast.error("Lß╗ùi khi l╞░u dß╗» liß╗çu");
        }
    };

    const handleDelete = async (id: number) => {
        if (!confirm("Bß║ín c├│ chß║»c muß╗æn x├│a banner n├áy?")) return;
        try {
            const res = await deleteAdminBanner(id);
            if (res.success) {
                toast.success("X├│a th├ánh c├┤ng!");
                fetchBanners();
            } else {
                toast.error(res.message);
            }
        } catch (error) {
            toast.error("Lß╗ùi khi x├│a");
        }
    };

    return (
        <div className="flex h-full flex-col p-6">
            <div className="mb-6 flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-on-surface">Quß║ún l├╜ Banner (CMS)</h1>
                    <p className="text-sm text-on-surface-variant">T├╣y chß╗ënh nß╗Öi dung tr├¼nh chiß║┐u trang chß╗º</p>
                </div>
                <button
                    onClick={() => handleOpenModal()}
                    className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-on-primary transition hover:bg-primary/90"
                >
                    <Plus size={18} />
                    Th├¬m Banner mß╗¢i
                </button>
            </div>

            {isLoading ? (
                <div className="flex h-64 items-center justify-center">
                    <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
                </div>
            ) : (
                <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                    {banners.map((banner) => (
                        <div key={banner.id} className="flex flex-col overflow-hidden rounded-xl border border-outline-variant/30 bg-surface shadow-sm">
                            <div className="relative h-48 bg-surface-variant">
                                <img src={banner.imageUrl} alt={banner.title} className="h-full w-full object-cover" />
                                <div className="absolute right-2 top-2 flex gap-1 rounded bg-black/50 p-1 backdrop-blur">
                                    <button onClick={() => handleOpenModal(banner)} className="p-1 text-white hover:text-primary"><Pencil size={16} /></button>
                                    <button onClick={() => handleDelete(banner.id)} className="p-1 text-white hover:text-error"><Trash2 size={16} /></button>
                                </div>
                                <div className="absolute left-2 top-2 rounded bg-black/50 px-2 py-1 text-xs font-semibold text-white backdrop-blur">
                                    Thß╗⌐ tß╗▒: {banner.displayOrder}
                                </div>
                            </div>
                            <div className="p-4">
                                <div className="flex items-start justify-between gap-2">
                                    <h3 className="font-semibold text-on-surface line-clamp-1">{banner.title}</h3>
                                    {banner.isActive ? <CheckCircle2 size={18} className="text-success flex-shrink-0" /> : <XCircle size={18} className="text-error flex-shrink-0" />}
                                </div>
                                <p className="mt-1 text-sm text-on-surface-variant line-clamp-2">{banner.description || "Kh├┤ng c├│ m├┤ tß║ú"}</p>
                            </div>
                        </div>
                    ))}
                    {banners.length === 0 && (
                        <div className="col-span-full flex flex-col items-center justify-center rounded-xl border border-dashed border-outline-variant p-12 text-on-surface-variant">
                            <LayoutDashboard size={48} className="mb-4 opacity-50" />
                            <p>Ch╞░a c├│ banner n├áo. H├úy th├¬m banner mß╗¢i ─æß╗â hiß╗ân thß╗ï tr├¬n trang chß╗º.</p>
                        </div>
                    )}
                </div>
            )}

            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 px-4 backdrop-blur-sm">
                    <div className="w-full max-w-lg rounded-2xl bg-surface p-6 shadow-xl">
                        <h2 className="mb-6 text-xl font-bold">{editingBanner ? "Sß╗¡a Banner" : "Th├¬m Banner mß╗¢i"}</h2>
                        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
                            <div>
                                <label className="mb-1 block text-sm font-medium">Ti├¬u ─æß╗ü *</label>
                                <input
                                    required
                                    className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                    value={form.title}
                                    onChange={(e) => setForm({ ...form, title: e.target.value })}
                                />
                            </div>
                            <div>
                                <label className="mb-1 block text-sm font-medium">M├┤ tß║ú</label>
                                <input
                                    className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                    value={form.description}
                                    onChange={(e) => setForm({ ...form, description: e.target.value })}
                                />
                            </div>
                            <div>
                                <label className="mb-1 block text-sm font-medium">Link ß║ónh (URL) *</label>
                                <input
                                    required
                                    type="url"
                                    className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                    value={form.imageUrl}
                                    onChange={(e) => setForm({ ...form, imageUrl: e.target.value })}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="mb-1 block text-sm font-medium">Thß╗⌐ tß╗▒ ╞░u ti├¬n</label>
                                    <input
                                        type="number"
                                        className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                        value={form.displayOrder}
                                        onChange={(e) => setForm({ ...form, displayOrder: Number(e.target.value) })}
                                    />
                                </div>
                                <div className="flex items-center pt-6">
                                    <label className="flex cursor-pointer items-center gap-2">
                                        <input
                                            type="checkbox"
                                            className="h-5 w-5 rounded border-outline-variant"
                                            checked={form.isActive}
                                            onChange={(e) => setForm({ ...form, isActive: e.target.checked })}
                                        />
                                        <span className="text-sm font-medium">K├¡ch hoß║ít hiß╗ân thß╗ï</span>
                                    </label>
                                </div>
                            </div>
                            <div className="mt-4 flex justify-end gap-3">
                                <button type="button" onClick={handleCloseModal} className="rounded-lg px-4 py-2 hover:bg-surface-variant">Hß╗ºy</button>
                                <button type="submit" className="rounded-lg bg-primary px-4 py-2 text-white hover:bg-primary/90">L╞░u th├┤ng tin</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

