"use client";
import { useEffect, useState } from "react";
import { BookOpen, CalendarDays, Loader2, User as UserIcon, X, Search, CheckCircle2 } from "lucide-react";
import { UI_TEXT } from "@/constants/ui-text";
import { API_ERRORS } from "@/constants/ui-text/shared/api";
import { createAdminBorrowOrder } from "@/services/adminBorrow";
import { lookupCustomer, AdminCustomerLookupResponse } from "@/services/adminCustomer";
import { toast } from "sonner";

const T = UI_TEXT.ADMIN_BORROW_MANAGEMENT.MODAL;

export default function BorrowModal({ open, onClose, onSubmitSuccess }: { open: boolean; onClose: () => void; onSubmitSuccess: () => void }) {
    const [form, setForm] = useState({
        phone: "",
        fullName: "",
        email: "",
        bookBarcodes: "",
        dueDate: "",
    });
    const [isLoading, setIsLoading] = useState(false);
    const [isLookingUp, setIsLookingUp] = useState(false);
    const [customerData, setCustomerData] = useState<AdminCustomerLookupResponse | null>(null);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (open) {
            setForm({ phone: "", fullName: "", email: "", bookBarcodes: "", dueDate: "" });
            setError(null);
            setIsLoading(false);
            setCustomerData(null);
            setIsLookingUp(false);
        }
    }, [open]);

    if (!open) return null;

    const handleLookup = async () => {
        if (!form.phone.trim()) {
            toast.error("Vui l├▓ng nhß║¡p sß╗æ ─æiß╗çn thoß║íi hoß║╖c m├ú thß║╗ th╞░ viß╗çn ─æß╗â t├¼m kiß║┐m.");
            return;
        }

        setIsLookingUp(true);
        setError(null);
        try {
            const res = await lookupCustomer(form.phone);
            if (res.success && res.data) {
                setCustomerData(res.data);
                setForm((prev) => ({
                    ...prev,
                    phone: res.data!.phone,
                    fullName: res.data!.fullName,
                    email: res.data!.email || "",
                }));
                toast.success("T├¼m thß║Ñy ─æß╗Öc giß║ú: " + res.data.fullName);
            } else {
                toast.error(res.message || "Kh├┤ng t├¼m thß║Ñy ─æß╗Öc giß║ú");
            }
        } catch (err: any) {
            toast.error(err.response?.data?.message || "Kh├┤ng t├¼m thß║Ñy ─æß╗Öc giß║ú");
            setCustomerData(null);
        } finally {
