"use client";

import { useEffect, useState } from "react";
import { AlertTriangle, Book, CheckCircle, X } from "lucide-react";
import { toast } from "sonner";
import { Skeleton } from "@/components/ui/skeleton";
import { ADMIN_BORROW_MANAGEMENT } from "@/constants/ui-text/admin/borrow-management";
import {
    AdminBorrowOrderDetailResponse,
    AdminReturnBookRequest,
    BookReturnDetailRequest,
    ReturnBookResponse,
    getAdminBorrowOrderDetail,
    returnBooks,
} from "@/services/adminBorrow";

const TEXT = ADMIN_BORROW_MANAGEMENT.RETURN_BOOK_MODAL;

interface ReturnBookModalProps {
    isOpen: boolean;
    onClose: () => void;
    orderCode: string | null;
    onSubmitSuccess: (data: ReturnBookResponse) => void;
}

export default function ReturnBookModal({ isOpen, onClose, orderCode, onSubmitSuccess }: ReturnBookModalProps) {
    const [detail, setDetail] = useState<AdminBorrowOrderDetailResponse | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const [isReturning, setIsReturning] = useState<Record<number, boolean>>({});
    const [conditions, setConditions] = useState<Record<number, "NORMAL" | "DAMAGED" | "LOST">>({});
    const [notes, setNotes] = useState<Record<number, string>>({});
    const [generalNote, setGeneralNote] = useState("");

    useEffect(() => {
        if (isOpen && orderCode) {
            fetchDetail();
            setIsReturning({});
            setConditions({});
            setNotes({});
            setGeneralNote("");
        } else {
            setDetail(null);
            setError(null);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isOpen, orderCode]);

    const fetchDetail = async () => {
        setIsLoading(true);
        setError(null);
        try {
            const res = await getAdminBorrowOrderDetail(orderCode!);
            if (res.success && res.data) {
                setDetail(res.data);
                const initialReturning: Record<number, boolean> = {};
                const initialConditions: Record<number, "NORMAL" | "DAMAGED" | "LOST"> = {};
                res.data.items.forEach((item) => {
                    const alreadyReturned = ["RETURNED", "LOST", "DAMAGED"].includes(item.status);
                    initialReturning[item.id] = !alreadyReturned;
                    initialConditions[item.id] = "NORMAL";
                });
                setIsReturning(initialReturning);
                setConditions(initialConditions);
            } else {
                setError(res.message || TEXT.ERROR_FETCH);
            }
        } catch (err) {
            setError(TEXT.ERROR_FETCH);
        } finally {
            setIsLoading(false);
        }
    };

    const handleReturningChange = (itemId: number, checked: boolean) => {
        setIsReturning((prev) => ({ ...prev, [itemId]: checked }));
    };

    const handleConditionChange = (itemId: number, condition: "NORMAL" | "DAMAGED" | "LOST") => {
        setConditions((prev) => ({ ...prev, [itemId]: condition }));
    };

    const handleNoteChange = (itemId: number, note: string) => {
        setNotes((prev) => ({ ...prev, [itemId]: note }));
    };

    const handleSubmit = async () => {
        if (!detail) return;
        setIsSubmitting(true);
        try {
            const details: BookReturnDetailRequest[] = detail.items
                .filter((item) => isReturning[item.id])
                .map((item) => ({
                    bookCopyId: item.bookCopyId,
                    conditionStatus: conditions[item.id] || "NORMAL",
                    note: notes[item.id] || undefined,
                }));

            if (details.length === 0) {
                toast.error(TEXT.ERROR_NO_BOOK_SELECTED);
                setIsSubmitting(false);
                return;
            }

            const payload: AdminReturnBookRequest = {
                borrowOrderId: detail.id,
                details,
                generalNote: generalNote || undefined,
            };

            const res = await returnBooks(detail.id, payload);
            if (res.success && res.data) {
                onSubmitSuccess(res.data);
                onClose();
            } else {
                toast.error(res.message || TEXT.ERROR_RETURN_FAILED);
            }
        } catch (err: any) {
            toast.error(err.response?.data?.message || TEXT.ERROR_GENERAL);
        } finally {
            setIsSubmitting(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
            <div className="flex max-h-[90vh] w-full max-w-3xl flex-col rounded-2xl bg-surface-container-lowest shadow-xl">
                {/* Header */}
                <div className="flex items-center justify-between border-b border-outline-variant/30 px-6 py-4">
                    <div>
                        <h2 className="text-xl font-bold text-on-surface">{TEXT.TITLE}</h2>
                        {orderCode && (
                            <div className="mt-2 space-y-1">
                                <p className="text-sm text-on-surface-variant">
                                    {TEXT.ORDER_CODE}: <span className="font-medium text-on-surface">{orderCode}</span>
                                </p>
                                {detail && (
                                    <p className="text-sm text-on-surface-variant">
                                        Kh├ích h├áng: <span className="font-medium text-on-surface">{detail.customerName}</span>
                                        {detail.isGuest && (
                                            <span className="ml-2 rounded bg-primary-100 px-1.5 py-0.5 text-[10px] font-semibold text-primary-700 dark:bg-primary-900 dark:text-primary-300">
                                                Kh├ích v├úng lai
                                            </span>
                                        )}
                                        {detail.customerPhone && (
                                            <span className="ml-2 text-on-surface-variant">({detail.customerPhone})</span>
                                        )}
                                    </p>
                                )}
                            </div>
                        )}
                    </div>
                    <button
                        onClick={onClose}
                        className="rounded-full p-2 text-on-surface-variant transition-colors hover:bg-surface-container-low hover:text-on-surface"
                    >
                        <X size={20} />
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-6">
                    {isLoading ? (
                        <div className="flex flex-col gap-6">
                            <Skeleton className="h-40 w-full rounded-xl" />
                        </div>
                    ) : error ? (
                        <div className="flex h-40 items-center justify-center text-error">{error}</div>
                    ) : detail ? (
                        <div className="flex flex-col gap-6">
                            {/* Books List */}
                            <div className="overflow-hidden rounded-xl border border-outline-variant/30">
                                <div className="flex items-center justify-between border-b border-outline-variant/30 bg-surface-container-low px-4 py-3 font-medium text-on-surface">
                                    <div className="flex items-center gap-2">
                                        <Book size={18} className="text-tertiary" />
                                        {TEXT.BOOK_STATUS_TITLE}
                                    </div>
                                    <div className="text-sm font-normal text-on-surface-variant">
                                        {TEXT.SELECTING_RETURN}{" "}
                                        <span className="font-bold text-primary">{Object.values(isReturning).filter(Boolean).length}</span> /{" "}
                                        {detail.items.filter((i) => !["RETURNED", "LOST", "DAMAGED"].includes(i.status)).length} {TEXT.BOOKS_UNIT}
                                    </div>
                                </div>
                                <div className="space-y-4 p-4">
                                    {detail.items.map((item) => {
                                        const alreadyReturned = ["RETURNED", "LOST", "DAMAGED"].includes(item.status);
                                        const active = isReturning[item.id] && !alreadyReturned;

                                        return (
                                            <div
                                                key={item.id}
                                                className={`rounded-lg border p-4 transition-colors ${alreadyReturned ? "border-outline-variant/30 bg-surface-container-lowest opacity-60" : active ? "border-primary/50 bg-primary/5" : "border-outline-variant/50"}`}
                                            >
                                                <div className="mb-2 flex items-start justify-between">
                                                    <div className="flex items-center gap-3">
                                                        {!alreadyReturned && (
                                                            <input
                                                                type="checkbox"
                                                                checked={isReturning[item.id] || false}
                                                                onChange={(e) => handleReturningChange(item.id, e.target.checked)}
                                                                className="h-5 w-5 rounded border-outline-variant text-primary focus:ring-primary"
                                                            />
                                                        )}
                                                        <div>
                                                            <div className="flex items-center gap-2 font-semibold text-on-surface">
                                                                {item.bookTitle}
                                                                {alreadyReturned && (
                                                                    <span className="bg-success/20 text-success rounded-full px-2 py-0.5 text-xs">
                                                                        {TEXT.ALREADY_RETURNED}
                                                                    </span>
                                                                )}
                                                            </div>
                                                            <div className="text-sm text-on-surface-variant">
                                                                {TEXT.BARCODE} {item.barcode}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>

                                                {!alreadyReturned && (
                                                    <div
                                                        className={`mt-3 grid grid-cols-1 gap-4 transition-opacity md:grid-cols-2 ${active ? "opacity-100" : "pointer-events-none opacity-40"}`}
                                                    >
                                                        <div>
                                                            <label className="mb-1 block text-sm font-medium">{TEXT.CONDITION}</label>
                                                            <select
                                                                value={conditions[item.id] || "NORMAL"}
                                                                onChange={(e) =>
                                                                    handleConditionChange(item.id, e.target.value as "NORMAL" | "DAMAGED" | "LOST")
                                                                }
                                                                disabled={!active}
                                                                className="w-full rounded-lg border border-outline-variant bg-transparent p-2.5 text-sm outline-none focus:border-primary focus:ring-1 focus:ring-primary disabled:bg-surface-container-low"
                                                            >
                                                                <option value="NORMAL">{TEXT.COND_NORMAL}</option>
                                                                <option value="DAMAGED">{TEXT.COND_DAMAGED}</option>
                                                                <option value="LOST">{TEXT.COND_LOST}</option>
                                                            </select>
                                                        </div>
                                                        <div>
                                                            <label className="mb-1 block text-sm font-medium">{TEXT.NOTE_OPTIONAL}</label>
                                                            <input
                                                                type="text"
                                                                value={notes[item.id] || ""}
                                                                onChange={(e) => handleNoteChange(item.id, e.target.value)}
                                                                disabled={!active}
                                                                placeholder="M├┤ tß║ú h╞░ hß╗Ång..."
                                                                className="w-full rounded-lg border border-outline-variant bg-transparent p-2.5 text-sm outline-none focus:border-primary focus:ring-1 focus:ring-primary disabled:bg-surface-container-low"
                                                            />
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>

                            {/* General Note */}
                            <div>
                                <label className="mb-1 block text-sm font-medium">{TEXT.GENERAL_NOTE}</label>
                                <textarea
                                    value={generalNote}
                                    onChange={(e) => setGeneralNote(e.target.value)}
                                    placeholder="V├¡ dß╗Ñ: Trß║ú thiß║┐u 1 cuß╗æn, kh├ích ─æß╗ün b├╣ sau..."
                                    rows={3}
                                    className="w-full rounded-lg border border-outline-variant bg-transparent p-3 text-sm outline-none focus:border-primary focus:ring-1 focus:ring-primary"
                                />
                            </div>

                            <div className="border-warning-container bg-warning-container/20 text-warning flex gap-3 rounded-xl border p-4">
                                <AlertTriangle size={24} className="shrink-0" />
                                <div className="text-sm">
                                    <span className="mb-1 block font-semibold">{TEXT.NOTICE}</span>
                                    {TEXT.NOTICE_DESC}
                                </div>
                            </div>
                        </div>
                    ) : null}
                </div>

                {/* Footer */}
                <div className="flex items-center justify-end gap-3 border-t border-outline-variant/30 px-6 py-4">
                    <button
                        onClick={onClose}
                        disabled={isSubmitting}
                        className="rounded-lg px-4 py-2 text-sm font-medium text-on-surface-variant transition-colors hover:bg-surface-container-low"
                    >
                        {TEXT.BTN_CANCEL}
                    </button>
                    <button
                        onClick={handleSubmit}
                        disabled={isSubmitting || !detail}
                        className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-on-primary transition-colors hover:bg-primary/90 disabled:opacity-50"
                    >
                        {isSubmitting ? (
                            <span className="h-5 w-5 animate-spin rounded-full border-2 border-on-primary border-t-transparent" />
                        ) : (
                            <CheckCircle size={18} />
                        )}
                        {TEXT.BTN_CONFIRM}
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { CheckCircle2, Receipt, X } from "lucide-react";
import { QRCodeSVG } from "qrcode.react";
import { toast } from "sonner";
import { ADMIN_BORROW_MANAGEMENT } from "@/constants/ui-text/admin/borrow-management";
import { formatCurrency } from "@/lib/utils";
import { type ReturnBookResponse, confirmReturnCashPayment, generateReturnVnPayUrl, getAdminBorrowOrderDetail } from "@/services/adminBorrow";

const TEXT = ADMIN_BORROW_MANAGEMENT.RETURN_INVOICE_MODAL;

interface ReturnInvoiceModalProps {
    isOpen: boolean;
    onClose: () => void;
    invoiceData: ReturnBookResponse | null;
}

export default function ReturnInvoiceModal({ isOpen, onClose, invoiceData }: ReturnInvoiceModalProps) {
    const [vnpayUrl, setVnpayUrl] = useState<string | null>(null);
    const [isGenerating, setIsGenerating] = useState(false);
    const [isConfirmingCash, setIsConfirmingCash] = useState(false);
    const [isCashConfirmed, setIsCashConfirmed] = useState(false);

    useEffect(() => {
        let interval: NodeJS.Timeout;
        if (isOpen && invoiceData?.orderCode && !isCashConfirmed && vnpayUrl) {
            // Poll every 3 seconds to check if status changed to RETURNED or PARTIALLY_RETURNED
            interval = setInterval(async () => {
                try {
                    const res = await getAdminBorrowOrderDetail(invoiceData.orderCode);
                    if (res.success && res.data) {
                        const status = res.data.status;
                        if (status === "RETURNED" || status === "PARTIALLY_RETURNED") {
                            toast.success(TEXT.SUCCESS_VNPAY_POLLING);
                            setIsCashConfirmed(true);
                            clearInterval(interval);
                            // Auto close modal to refresh the list
                            setTimeout(() => {
                                onClose();
                            }, 2000);
                        }
                    }
                } catch (error) {
                    // Ignore polling errors
                }
            }, 3000);
        }

        return () => {
            if (interval) clearInterval(interval);
        };
    }, [isOpen, invoiceData?.orderCode, isCashConfirmed, vnpayUrl, onClose]);

    const handleGenerateVnPay = async () => {
        if (!invoiceData?.bookReturnId) return;
        setIsGenerating(true);
        try {
            const res = await generateReturnVnPayUrl(invoiceData.bookReturnId);
            if (res.success && res.data) {
                setVnpayUrl(res.data);
                toast.success(TEXT.SUCCESS_VNPAY);
            } else {
                toast.error(res.message || TEXT.ERROR_VNPAY);
            }
        } catch (error) {
            toast.error(TEXT.ERROR_CONN_VNPAY);
        } finally {
            setIsGenerating(false);
        }
    };

    const handleConfirmCash = async () => {
        if (!invoiceData?.bookReturnId) return;
        setIsConfirmingCash(true);
        try {
            const res = await confirmReturnCashPayment(invoiceData.bookReturnId);
            if (res.success) {
                toast.success(TEXT.SUCCESS_CASH);
                setIsCashConfirmed(true);
            } else {
                toast.error(res.message || TEXT.ERROR_CASH);
            }
        } catch (error) {
            toast.error(TEXT.ERROR_CONN_CASH);
        } finally {
            setIsConfirmingCash(false);
        }
    };

    // Reset state when closed
    useEffect(() => {
        if (!isOpen) {
            setVnpayUrl(null);
            setIsCashConfirmed(false);
            setIsGenerating(false);
            setIsConfirmingCash(false);
        }
    }, [isOpen]);

    if (!isOpen || !invoiceData) return null;

    const isRefund = invoiceData.totalAmountToPay < 0;
    const absAmount = Math.abs(invoiceData.totalAmountToPay);
    const requiresAction = invoiceData.totalAmountToPay !== 0 && !isCashConfirmed;

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
            <div className="animate-in zoom-in-95 flex max-h-[90vh] w-full max-w-md flex-col overflow-hidden rounded-2xl bg-surface-container-lowest shadow-2xl duration-200">
                {/* Header */}
                <div className="relative flex flex-col items-center justify-center bg-primary/10 px-6 py-8 text-center">
                    <button
                        onClick={onClose}
                        className="absolute right-4 top-4 rounded-full p-2 text-on-surface-variant transition-colors hover:bg-surface-container-low hover:text-on-surface"
                    >
                        <X size={20} />
                    </button>
                    <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-primary text-on-primary shadow-lg shadow-primary/30">
                        <CheckCircle2 size={36} />
                    </div>
                    <h2 className="text-2xl font-bold text-on-surface">{TEXT.TITLE}</h2>
                    <p className="mt-1 text-sm text-on-surface-variant">
                        {TEXT.ORDER_CODE} {invoiceData.orderCode}
                    </p>
                </div>

                {/* Body - Invoice Details */}
                <div className="min-h-0 flex-1 overflow-y-auto p-6">
                    <div className="mb-4 flex items-center gap-2 font-semibold text-on-surface">
                        <Receipt size={18} className="text-primary" />
                        {TEXT.BOOK_DETAILS}
                    </div>

                    <div className="mb-6 space-y-2">
                        {invoiceData.details?.map((detail, idx) => (
                            <div key={idx} className="flex items-start justify-between rounded-lg border border-outline-variant/20 bg-surface p-3 text-sm">
                                <div className="flex-1 pr-4">
                                    <p className="line-clamp-1 font-medium text-on-surface">{detail.bookTitle}</p>
                                    <p className="mt-1 text-xs text-on-surface-variant">
                                        {TEXT.LABEL_CODE} {detail.barcode} ΓÇó {TEXT.LABEL_STATUS}{" "}
                                        {detail.conditionStatus === "NORMAL"
                                            ? TEXT.COND_NORMAL
                                            : detail.conditionStatus === "DAMAGED"
                                              ? TEXT.COND_DAMAGED
                                              : TEXT.COND_LOST}
                                    </p>
                                    {detail.note && (
                                        <p className="mt-1 text-xs italic text-on-surface-variant">
                                            {TEXT.LABEL_NOTE} {detail.note}
                                        </p>
                                    )}
                                </div>
                                {detail.fineAmount > 0 && (
                                    <div className="whitespace-nowrap text-right">
                                        <p className="text-xs text-on-surface-variant">{TEXT.LABEL_FINE}</p>
                                        <p className="font-medium text-error">{formatCurrency(detail.fineAmount)}</p>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>

                    <div className="mb-4 flex items-center gap-2 font-semibold text-on-surface">
                        <Receipt size={18} className="text-primary" />
                        {TEXT.COST_SUMMARY}
                    </div>

                    <div className="space-y-3 rounded-xl border border-outline-variant/30 bg-surface-container-low/50 p-4">
                        <div className="flex justify-between text-sm">
                            <span className="text-on-surface-variant">{TEXT.RENT_FEE}</span>
                            <span className="font-medium text-on-surface">{formatCurrency(invoiceData.subtotalFee)}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                            <span className="text-on-surface-variant">{TEXT.FINE_FEE}</span>
                            <span className="font-medium text-error">{formatCurrency(invoiceData.totalFineAmount)}</span>
                        </div>
                        <div className="my-2 h-px w-full bg-outline-variant/30"></div>
                        <div className="flex justify-between text-sm">
                            <span className="text-on-surface-variant">{TEXT.TOTAL_COST}</span>
                            <span className="font-medium text-on-surface">{formatCurrency(invoiceData.subtotalFee + invoiceData.totalFineAmount)}</span>
                        </div>
                        <div className="flex justify-between text-sm">
                            <span className="text-on-surface-variant">{TEXT.DEPOSIT_PAID}</span>
                            <span className="text-success font-medium">-{formatCurrency(invoiceData.totalDeposit)}</span>
                        </div>
                    </div>

                    <div
                        className={`mt-6 rounded-xl border p-4 ${isRefund ? "bg-success/10 border-success/20" : invoiceData.totalAmountToPay > 0 ? "border-error/20 bg-error/10" : "border-outline-variant/30 bg-surface-container-low"}`}
                    >
                        <div className="flex items-center justify-between">
                            <span
                                className={`font-semibold ${isRefund ? "text-success" : invoiceData.totalAmountToPay > 0 ? "text-error" : "text-on-surface"}`}
                            >
                                {isRefund ? TEXT.REFUND_AMOUNT : invoiceData.totalAmountToPay > 0 ? TEXT.COLLECT_AMOUNT : TEXT.PAID_AMOUNT}
                            </span>
                            <span
                                className={`text-xl font-bold ${isRefund ? "text-success" : invoiceData.totalAmountToPay > 0 ? "text-error" : "text-on-surface"}`}
                            >
                                {formatCurrency(absAmount)}
                            </span>
                        </div>
                        {requiresAction && invoiceData.totalAmountToPay > 0 && <p className="mt-2 text-xs text-error/80">{TEXT.REQUIRE_COLLECT}</p>}
                        {requiresAction && isRefund && <p className="text-success/80 mt-2 text-xs">{TEXT.REQUIRE_REFUND}</p>}
                        {isCashConfirmed && (
                            <div className="text-success mt-3 flex items-center gap-1.5 text-sm font-medium">
                                <CheckCircle2 size={16} /> {TEXT.CASH_CONFIRMED}
                            </div>
                        )}
                    </div>

                    {requiresAction && invoiceData.totalAmountToPay > 0 && (
                        <div className="mt-4 flex flex-col gap-3">
                            <div className="flex items-center gap-3">
                                <button
                                    onClick={handleConfirmCash}
                                    disabled={isConfirmingCash || isGenerating}
                                    className="flex-1 rounded-lg border border-primary px-4 py-2.5 text-sm font-medium text-primary transition-colors hover:bg-primary/5 disabled:opacity-50"
                                >
                                    {isConfirmingCash ? TEXT.STATUS_PROCESSING : TEXT.BTN_CASH_PAY}
                                </button>
                                <button
                                    onClick={handleGenerateVnPay}
                                    disabled={isConfirmingCash || isGenerating || !!vnpayUrl}
                                    className="flex-1 rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-medium text-white transition-colors hover:bg-blue-700 disabled:opacity-50"
                                >
                                    {isGenerating ? TEXT.STATUS_GENERATING : TEXT.BTN_VNPAY}
                                </button>
                            </div>

                            {vnpayUrl && (
                                <div className="animate-in slide-in-from-top-4 mt-2 flex flex-col items-center rounded-xl border border-blue-200 bg-blue-50 p-4">
                                    <p className="mb-3 text-sm font-medium text-blue-800">{TEXT.SCAN_VNPAY}</p>
                                    <div className="rounded-lg bg-white p-2 shadow-sm">
                                        <QRCodeSVG value={vnpayUrl} size={160} level="H" includeMargin={true} />
                                    </div>
                                    <a
                                        href={vnpayUrl}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-3 text-xs text-blue-600 underline hover:text-blue-800"
                                    >
                                        {TEXT.OPEN_LINK_NEW_TAB}
                                    </a>
                                    <div className="mt-4 flex items-center justify-center gap-2 text-sm font-medium text-blue-600">
                                        <div className="h-4 w-4 animate-spin rounded-full border-2 border-blue-600 border-t-transparent"></div>
                                        <span>{TEXT.WAITING_CONFIRMATION}</span>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {requiresAction && isRefund && (
                        <div className="mt-4">
                            <button
                                onClick={handleConfirmCash}
                                disabled={isConfirmingCash}
                                className="bg-success hover:bg-success/90 w-full rounded-lg px-4 py-2.5 text-sm font-medium text-white transition-colors disabled:opacity-50"
                            >
                                {isConfirmingCash ? TEXT.STATUS_PROCESSING : TEXT.BTN_CASH_REFUND}
                            </button>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="flex items-center gap-3 border-t border-outline-variant/30 bg-surface-container-lowest px-6 py-4 print:hidden">
                    <button
                        onClick={() => window.print()}
                        className="flex items-center justify-center gap-2 rounded-lg border border-outline-variant px-4 py-2.5 text-sm font-medium text-on-surface transition-colors hover:bg-surface-container-low"
                    >
                        <Receipt size={18} /> In bi├¬n lai
                    </button>
                    <button
                        onClick={onClose}
                        className="flex-1 rounded-lg bg-primary px-4 py-2.5 text-sm font-medium text-on-primary transition-colors hover:bg-primary/90"
                    >
                        {TEXT.BTN_COMPLETE}
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";
