"use client";

import { useEffect, useState } from "react";
import { X, Search, Plus, Trash2, Loader2, LibraryBig } from "lucide-react";
import { toast } from "sonner";
import { formatCurrency } from "@/lib/utils";
import { createAdminStockReceipt } from "@/services/adminStockReceipt";
import { getAdminSuppliers, AdminSupplier, createAdminSupplier } from "@/services/adminSupplier";
import { bookService } from "@/services/book";
import type { BookListItem } from "@/types/book";

interface CreateReceiptModalProps {
    onClose: () => void;
    onSuccess: () => void;
}

interface SelectedBook extends BookListItem {
    importQuantity: number;
    importPrice: number;
}

export default function CreateReceiptModal({ onClose, onSuccess }: CreateReceiptModalProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [suppliers, setSuppliers] = useState<AdminSupplier[]>([]);
    
    const [selectedSupplierId, setSelectedSupplierId] = useState<number>(0);
    const [note, setNote] = useState("");
    
    // Quick Add Supplier
    const [isAddingSupplier, setIsAddingSupplier] = useState(false);
    const [newSupplierName, setNewSupplierName] = useState("");

    // Book Search
    const [searchKeyword, setSearchKeyword] = useState("");
    const [searchResults, setSearchResults] = useState<BookListItem[]>([]);
    const [isSearching, setIsSearching] = useState(false);

    // Selected Books Cart
    const [selectedBooks, setSelectedBooks] = useState<SelectedBook[]>([]);

    useEffect(() => {
        fetchSuppliers();
    }, []);

    const fetchSuppliers = async () => {
        try {
            const res = await getAdminSuppliers();
            if (res.success && res.data) {
                setSuppliers(res.data);
                if (res.data.length > 0) setSelectedSupplierId(res.data[0].id);
            }
        } catch (error) {
            toast.error("Kh├┤ng thß╗â tß║úi danh s├ích nh├á cung cß║Ñp");
        }
    };

    const handleQuickAddSupplier = async () => {
        if (!newSupplierName.trim()) return;
        try {
            const res = await createAdminSupplier({ name: newSupplierName, phone: "", email: "", address: "", isActive: true });
            if (res.success && res.data) {
                toast.success("Th├¬m nh├á cung cß║Ñp th├ánh c├┤ng!");
                await fetchSuppliers();
                setSelectedSupplierId(res.data.id);
                setIsAddingSupplier(false);
                setNewSupplierName("");
            }
        } catch (error) {
            toast.error("Lß╗ùi th├¬m nh├á cung cß║Ñp");
        }
    };

    const handleSearchBooks = async () => {
        if (!searchKeyword.trim()) return;
        setIsSearching(true);
        try {
            const res = await bookService.getAdminBookInventory(0, 10, searchKeyword);
            if (res && res.content) {
                setSearchResults(res.content);
            }
        } catch (error) {
            toast.error("Lß╗ùi t├¼m kiß║┐m s├ích");
        } finally {
            setIsSearching(false);
        }
    };

    const handleAddBookToReceipt = (book: BookListItem) => {
        if (selectedBooks.find(b => b.id === book.id)) {
            toast.warning("S├ích n├áy ─æ├ú c├│ trong danh s├ích nhß║¡p!");
            return;
        }
        setSelectedBooks([...selectedBooks, { ...book, importQuantity: 1, importPrice: 0 }]);
        setSearchKeyword("");
        setSearchResults([]);
    };

    const handleRemoveBook = (bookId: number) => {
        setSelectedBooks(selectedBooks.filter(b => b.id !== bookId));
    };

    const handleUpdateBook = (bookId: number, field: "importQuantity" | "importPrice", value: number) => {
        setSelectedBooks(selectedBooks.map(b => b.id === bookId ? { ...b, [field]: value } : b));
    };

    const handleSubmit = async () => {
        if (!selectedSupplierId) {
            toast.error("Vui l├▓ng chß╗ìn nh├á cung cß║Ñp");
            return;
        }
        if (selectedBooks.length === 0) {
            toast.error("Vui l├▓ng th├¬m ├¡t nhß║Ñt mß╗Öt loß║íi s├ích v├áo phiß║┐u nhß║¡p");
            return;
        }
        
        // Validate quantities and prices
        for (const b of selectedBooks) {
            if (b.importQuantity <= 0) {
                toast.error(`S├ích "${b.title}" phß║úi c├│ sß╗æ l╞░ß╗úng > 0`);
                return;
            }
            if (b.importPrice < 0) {
                toast.error(`S├ích "${b.title}" c├│ gi├í nhß║¡p kh├┤ng hß╗úp lß╗ç`);
                return;
            }
        }

        setIsLoading(true);
        try {
            const details = selectedBooks.map(b => ({
                bookId: b.id,
                quantity: b.importQuantity,
                unitPrice: b.importPrice,
            }));

            const res = await createAdminStockReceipt({
                supplierId: selectedSupplierId,
                note: note,
                details: details,
            });

            if (res.success) {
                toast.success("Lß║¡p phiß║┐u nhß║¡p th├ánh c├┤ng! Hß╗ç thß╗æng ─æ├ú tß╗▒ ─æß╗Öng cß╗Öng kho v├á sinh m├ú s├ích mß╗¢i.");
                onSuccess();
            } else {
                toast.error(res.message || "Lß║¡p phiß║┐u nhß║¡p thß║Ñt bß║íi");
            }
        } catch (error) {
            toast.error("─É├ú xß║úy ra lß╗ùi hß╗ç thß╗æng");
        } finally {
            setIsLoading(false);
        }
    };

    const totalAmount = selectedBooks.reduce((sum, b) => sum + (b.importQuantity * b.importPrice), 0);

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 px-4 py-8 backdrop-blur-sm">
            <div className="flex h-full w-full max-w-5xl flex-col overflow-hidden rounded-2xl bg-surface shadow-2xl">
                {/* Header */}
                <div className="flex items-center justify-between border-b border-outline-variant/30 bg-surface-container-low px-6 py-4">
                    <h2 className="text-xl font-bold">Lß║¡p Phiß║┐u Nhß║¡p Kho</h2>
                    <button onClick={onClose} className="rounded-full p-2 hover:bg-outline-variant/30"><X size={20} /></button>
                </div>

                {/* Body */}
                <div className="flex flex-1 overflow-hidden">
                    {/* Left: Form & Search */}
                    <div className="flex w-1/3 flex-col border-r border-outline-variant/30 p-6 overflow-y-auto">
                        <div className="mb-6 flex flex-col gap-1.5">
                            <label className="text-sm font-medium">Nh├á cung cß║Ñp *</label>
                            {isAddingSupplier ? (
                                <div className="flex gap-2">
                                    <input 
                                        autoFocus
                                        placeholder="T├¬n nh├á cung cß║Ñp mß╗¢i..." 
                                        className="flex-1 rounded-lg border border-outline-variant p-2 text-sm"
                                        value={newSupplierName}
                                        onChange={e => setNewSupplierName(e.target.value)}
                                    />
                                    <button onClick={handleQuickAddSupplier} className="rounded-lg bg-primary px-3 text-sm text-white">L╞░u</button>
                                    <button onClick={() => setIsAddingSupplier(false)} className="rounded-lg bg-surface-variant px-3 text-sm">Hß╗ºy</button>
                                </div>
                            ) : (
                                <div className="flex gap-2">
                                    <select 
                                        className="flex-1 rounded-lg border border-outline-variant bg-surface-container-low p-2 text-sm"
                                        value={selectedSupplierId}
                                        onChange={(e) => setSelectedSupplierId(Number(e.target.value))}
                                    >
                                        <option value={0} disabled>-- Chß╗ìn nh├á cung cß║Ñp --</option>
                                        {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                                    </select>
                                    <button onClick={() => setIsAddingSupplier(true)} className="rounded-lg border border-outline-variant px-2 hover:bg-surface-variant" title="Th├¬m NCC mß╗¢i">
                                        <Plus size={18} />
                                    </button>
                                </div>
                            )}
                        </div>

                        <div className="mb-6 flex flex-col gap-1.5">
                            <label className="text-sm font-medium">Ghi ch├║ phiß║┐u nhß║¡p</label>
                            <textarea 
                                rows={2}
                                className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2 text-sm"
                                placeholder="Ghi ch├║ th├¬m..."
                                value={note}
                                onChange={e => setNote(e.target.value)}
                            />
                        </div>

                        <div className="my-4 h-px w-full bg-outline-variant/30"></div>

                        <div className="flex flex-col gap-1.5">
                            <label className="text-sm font-medium">T├¼m s├ích v├áo kho</label>
                            <div className="flex gap-2">
                                <input 
                                    placeholder="T├¬n s├ích, ISBN..." 
                                    className="flex-1 rounded-lg border border-outline-variant bg-surface-container-low p-2 text-sm"
                                    value={searchKeyword}
                                    onChange={e => setSearchKeyword(e.target.value)}
                                    onKeyDown={e => e.key === 'Enter' && handleSearchBooks()}
                                />
                                <button onClick={handleSearchBooks} className="rounded-lg bg-surface-variant px-3 hover:bg-outline-variant/30">
                                    {isSearching ? <Loader2 size={18} className="animate-spin" /> : <Search size={18} />}
                                </button>
                            </div>
                        </div>

                        {searchResults.length > 0 && (
                            <div className="mt-4 flex flex-col gap-2 rounded-lg border border-outline-variant/50 p-2 max-h-64 overflow-y-auto">
                                {searchResults.map(book => (
                                    <div key={book.id} className="flex items-center justify-between rounded p-2 hover:bg-surface-variant/50 border-b border-outline-variant/20 last:border-0">
                                        <div className="flex items-center gap-2 overflow-hidden">
                                            {book.imageUrl ? (
                                                <img src={book.imageUrl} className="h-10 w-8 object-cover rounded" />
                                            ) : (
                                                <div className="h-10 w-8 bg-surface-variant flex items-center justify-center rounded"><LibraryBig size={14} /></div>
                                            )}
                                            <div className="text-xs">
                                                <p className="font-semibold line-clamp-1">{book.title}</p>
                                                <p className="text-on-surface-variant line-clamp-1">{book.authors?.map(a => a.name).join(", ") || "Ch╞░a r├╡"}</p>
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => handleAddBookToReceipt(book)}
                                            className="rounded bg-primary/10 p-1.5 text-primary hover:bg-primary hover:text-white transition-colors ml-2 flex-shrink-0"
                                        >
                                            <Plus size={16} />
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Right: Selected Books Table */}
                    <div className="flex w-2/3 flex-col bg-surface-container-lowest p-6">
                        <h3 className="mb-4 font-bold">Danh s├ích mß║╖t h├áng nhß║¡p ({selectedBooks.length})</h3>
                        <div className="flex-1 overflow-y-auto border rounded-xl border-outline-variant/30">
                            <table className="w-full text-left text-sm">
                                <thead className="bg-surface-container-low sticky top-0 shadow-sm z-10">
                                    <tr>
                                        <th className="p-3 font-semibold">T├¬n s├ích</th>
                                        <th className="p-3 font-semibold w-24 text-center">SL</th>
                                        <th className="p-3 font-semibold w-32 text-right">─É╞ín gi├í (VN─É)</th>
                                        <th className="p-3 font-semibold w-32 text-right">Th├ánh tiß╗ün</th>
                                        <th className="p-3 font-semibold w-12 text-center"></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {selectedBooks.length === 0 ? (
                                        <tr>
                                            <td colSpan={5} className="p-12 text-center text-on-surface-variant">
                                                Ch╞░a chß╗ìn s├ích n├áo. H├úy t├¼m s├ích ß╗ƒ cß╗Öt b├¬n tr├íi v├á th├¬m v├áo danh s├ích.
                                            </td>
                                        </tr>
                                    ) : (
                                        selectedBooks.map(book => (
                                            <tr key={book.id} className="border-b border-outline-variant/20 hover:bg-surface-variant/10">
                                                <td className="p-3">
                                                    <p className="font-medium line-clamp-1">{book.title}</p>
                                                    <p className="text-xs text-on-surface-variant">ISBN: {book.isbn}</p>
                                                </td>
                                                <td className="p-2">
                                                    <input 
                                                        type="number" 
                                                        min="1"
                                                        className="w-full rounded border border-outline-variant p-1.5 text-center text-sm"
                                                        value={book.importQuantity}
                                                        onChange={e => handleUpdateBook(book.id, "importQuantity", Number(e.target.value))}
                                                    />
                                                </td>
                                                <td className="p-2">
                                                    <input 
                                                        type="number" 
                                                        min="0"
                                                        step="1000"
                                                        className="w-full rounded border border-outline-variant p-1.5 text-right text-sm"
                                                        value={book.importPrice}
                                                        onChange={e => handleUpdateBook(book.id, "importPrice", Number(e.target.value))}
                                                    />
                                                </td>
                                                <td className="p-3 text-right font-medium text-error">
                                                    {formatCurrency(book.importQuantity * book.importPrice)}
                                                </td>
                                                <td className="p-3 text-center">
                                                    <button onClick={() => handleRemoveBook(book.id)} className="text-on-surface-variant hover:text-error">
                                                        <Trash2 size={18} />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                        
                        <div className="mt-6 flex items-center justify-between rounded-xl bg-primary/5 p-4 border border-primary/20">
                            <div>
                                <p className="text-sm text-on-surface-variant">Tß╗òng gi├í trß╗ï phiß║┐u nhß║¡p</p>
                                <p className="text-2xl font-bold text-error">{formatCurrency(totalAmount)}</p>
                            </div>
                            <div className="flex gap-3">
                                <button onClick={onClose} className="rounded-lg px-6 py-2.5 font-medium hover:bg-surface-variant">Hß╗ºy</button>
                                <button 
                                    onClick={handleSubmit} 
                                    disabled={isLoading || selectedBooks.length === 0}
                                    className="flex items-center gap-2 rounded-lg bg-primary px-6 py-2.5 font-medium text-white shadow hover:bg-primary/90 disabled:opacity-50"
                                >
                                    {isLoading && <Loader2 size={18} className="animate-spin" />}
                                    Ho├án tß║Ñt & Nhß║¡p kho
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { ClipboardList, Plus, FileText, Search, Package, Calendar } from "lucide-react";
import { toast } from "sonner";
import { formatCurrency, formatDate } from "@/lib/utils";
import { AdminStockReceipt, getAdminStockReceipts, getAdminStockReceiptDetail } from "@/services/adminStockReceipt";
import CreateReceiptModal from "./CreateReceiptModal";

export default function InventoryManagement() {
    const [receipts, setReceipts] = useState<AdminStockReceipt[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [selectedReceipt, setSelectedReceipt] = useState<AdminStockReceipt | null>(null);

    useEffect(() => {
        fetchReceipts();
    }, []);

    const fetchReceipts = async () => {
        setIsLoading(true);
        try {
            const res = await getAdminStockReceipts();
            if (res.success && res.data) {
                setReceipts(res.data);
            } else {
                toast.error(res.message || "Lß╗ùi tß║úi dß╗» liß╗çu");
            }
        } catch (error) {
            toast.error("Lß╗ùi kß║┐t nß╗æi server");
        } finally {
            setIsLoading(false);
        }
    };

    const handleViewDetail = async (id: number) => {
        try {
            const res = await getAdminStockReceiptDetail(id);
            if (res.success && res.data) {
                setSelectedReceipt(res.data);
            }
        } catch (error) {
            toast.error("Kh├┤ng thß╗â tß║úi chi tiß║┐t phiß║┐u nhß║¡p");
        }
    };

    return (
        <div className="flex h-full flex-col p-6">
            <div className="mb-6 flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-on-surface">Quß║ún l├╜ Nhß║¡p kho</h1>
                    <p className="text-sm text-on-surface-variant">Lß║¡p phiß║┐u nhß║¡p v├á quß║ún l├╜ sß╗æ l╞░ß╗úng s├ích</p>
                </div>
                <button
                    onClick={() => setIsCreateModalOpen(true)}
                    className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-on-primary transition hover:bg-primary/90"
                >
                    <Plus size={18} />
                    Lß║¡p Phiß║┐u Nhß║¡p
                </button>
            </div>

            <div className="flex flex-1 flex-col gap-6 lg:flex-row">
                {/* List of Receipts */}
                <div className="flex w-full flex-col overflow-hidden rounded-xl border border-outline-variant/30 bg-surface shadow-sm lg:w-1/3">
                    <div className="border-b border-outline-variant/30 bg-surface-container-low p-4">
                        <h3 className="font-bold">Danh s├ích phiß║┐u nhß║¡p</h3>
                    </div>
                    <div className="hide-scrollbar flex-1 overflow-y-auto">
                        {isLoading ? (
                            <div className="flex h-32 items-center justify-center">
                                <div className="h-6 w-6 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
                            </div>
                        ) : receipts.length === 0 ? (
                            <div className="flex h-32 flex-col items-center justify-center text-on-surface-variant">
                                <ClipboardList size={32} className="mb-2 opacity-50" />
                                <span className="text-sm">Ch╞░a c├│ phiß║┐u nhß║¡p n├áo</span>
                            </div>
                        ) : (
                            <div className="flex flex-col">
                                {receipts.map((r) => (
                                    <button
                                        key={r.id}
                                        onClick={() => handleViewDetail(r.id)}
                                        className={`flex flex-col gap-1 border-b border-outline-variant/20 p-4 text-left transition-colors hover:bg-surface-variant/50 ${selectedReceipt?.id === r.id ? "bg-primary/10 border-l-4 border-l-primary" : "border-l-4 border-l-transparent"}`}
                                    >
                                        <div className="flex items-center justify-between">
                                            <span className="font-semibold text-primary">{r.receiptCode}</span>
                                            <span className="text-xs text-on-surface-variant">{r.createdAt ? formatDate(r.createdAt) : ""}</span>
                                        </div>
                                        <div className="text-sm text-on-surface line-clamp-1">{r.supplierName}</div>
                                        <div className="text-sm font-semibold text-error">{formatCurrency(r.totalAmount)}</div>
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {/* Receipt Details */}
                <div className="flex w-full flex-1 flex-col overflow-hidden rounded-xl border border-outline-variant/30 bg-surface shadow-sm lg:w-2/3">
                    {selectedReceipt ? (
                        <>
                            <div className="border-b border-outline-variant/30 bg-primary/5 p-6">
                                <div className="flex items-center justify-between mb-4">
                                    <h2 className="text-xl font-bold text-primary">Chi tiß║┐t: {selectedReceipt.receiptCode}</h2>
