"use client";

import { useEffect, useState } from "react";
import { Plus, Pencil, Trash2, Shield, Users } from "lucide-react";
import { toast } from "sonner";
import {
    AdminMembershipTier,
    getAdminMembershipTiers,
    createAdminMembershipTier,
    updateAdminMembershipTier,
    deleteAdminMembershipTier,
} from "@/services/adminMembershipTier";

export default function MembershipTierManagement() {
    const [tiers, setTiers] = useState<AdminMembershipTier[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingTier, setEditingTier] = useState<AdminMembershipTier | null>(null);

    const [form, setForm] = useState({
        name: "",
        minPoints: 0,
        discountPercent: 0,
        maxBorrowDays: 14,
        maxBorrowBooks: 5,
    });

    useEffect(() => {
        fetchTiers();
    }, []);

    const fetchTiers = async () => {
        setIsLoading(true);
        try {
            const res = await getAdminMembershipTiers();
            if (res.success && res.data) {
                // Sß║»p xß║┐p theo ─æiß╗âm t─âng dß║ºn
                setTiers(res.data.sort((a, b) => a.minPoints - b.minPoints));
            } else {
                toast.error(res.message || "Lß╗ùi tß║úi dß╗» liß╗çu");
            }
        } catch (error) {
            toast.error("Lß╗ùi kß║┐t nß╗æi");
        } finally {
            setIsLoading(false);
        }
    };

    const handleOpenModal = (tier?: AdminMembershipTier) => {
        if (tier) {
            setEditingTier(tier);
            setForm({
                name: tier.name,
                minPoints: tier.minPoints,
                discountPercent: tier.discountPercent,
                maxBorrowDays: tier.maxBorrowDays,
                maxBorrowBooks: tier.maxBorrowBooks,
            });
        } else {
            setEditingTier(null);
            setForm({
                name: "",
                minPoints: 0,
                discountPercent: 0,
                maxBorrowDays: 14,
                maxBorrowBooks: 5,
            });
        }
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setIsModalOpen(false);
        setEditingTier(null);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            if (editingTier) {
                const res = await updateAdminMembershipTier(editingTier.id, form);
                if (res.success) {
                    toast.success("Cß║¡p nhß║¡t th├ánh c├┤ng!");
                    fetchTiers();
                    handleCloseModal();
                } else {
                    toast.error(res.message);
                }
            } else {
                const res = await createAdminMembershipTier(form);
                if (res.success) {
                    toast.success("Th├¬m mß╗¢i th├ánh c├┤ng!");
                    fetchTiers();
                    handleCloseModal();
                } else {
                    toast.error(res.message);
                }
            }
        } catch (error) {
            toast.error("Lß╗ùi khi l╞░u dß╗» liß╗çu");
        }
    };

    const handleDelete = async (id: number) => {
        if (!confirm("Bß║ín c├│ chß║»c muß╗æn x├│a hß║íng th├ánh vi├¬n n├áy?")) return;
        try {
            const res = await deleteAdminMembershipTier(id);
            if (res.success) {
                toast.success("X├│a th├ánh c├┤ng!");
                fetchTiers();
            } else {
                toast.error(res.message);
            }
        } catch (error) {
            toast.error("Lß╗ùi khi x├│a");
        }
    };

    return (
        <div className="flex h-full flex-col p-6">
            <div className="mb-6 flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-on-surface">Quß║ún l├╜ Hß║íng th├ánh vi├¬n</h1>
                    <p className="text-sm text-on-surface-variant">Thiß║┐t lß║¡p c├íc cß║Ñp ─æß╗Ö v├á quyß╗ün lß╗úi cho ─æß╗Öc giß║ú</p>
                </div>
                <button
                    onClick={() => handleOpenModal()}
                    className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-on-primary transition hover:bg-primary/90"
                >
                    <Plus size={18} />
                    Th├¬m Hß║íng mß╗¢i
                </button>
            </div>

            {isLoading ? (
                <div className="flex h-64 items-center justify-center">
                    <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
                </div>
            ) : (
                <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                    {tiers.map((tier) => (
                        <div key={tier.id} className="relative overflow-hidden rounded-xl border border-outline-variant/30 bg-surface shadow-sm">
                            <div className="absolute right-3 top-3 flex gap-2">
                                <button onClick={() => handleOpenModal(tier)} className="text-on-surface-variant hover:text-primary">
                                    <Pencil size={18} />
                                </button>
                                <button onClick={() => handleDelete(tier.id)} className="text-on-surface-variant hover:text-error">
                                    <Trash2 size={18} />
                                </button>
                            </div>
                            
                            <div className="bg-primary/10 p-5 text-center">
                                <div className="mx-auto mb-3 flex h-14 w-14 items-center justify-center rounded-full bg-primary text-on-primary shadow-lg">
                                    <Shield size={28} />
                                </div>
                                <h3 className="text-lg font-bold text-on-surface">{tier.name}</h3>
                                <div className="mt-1 inline-flex items-center gap-1.5 rounded-full bg-surface px-3 py-1 text-xs font-semibold text-primary">
                                    <Users size={14} /> Mß╗æc ─æiß╗âm: {tier.minPoints}
                                </div>
                            </div>
                            
                            <div className="flex flex-col gap-3 p-5 text-sm">
                                <div className="flex justify-between border-b border-outline-variant/20 pb-2">
                                    <span className="text-on-surface-variant">Giß║úm gi├í ph├¡ m╞░ß╗ún:</span>
                                    <span className="font-semibold text-success">{tier.discountPercent}%</span>
                                </div>
                                <div className="flex justify-between border-b border-outline-variant/20 pb-2">
                                    <span className="text-on-surface-variant">S├ích m╞░ß╗ún tß╗æi ─æa:</span>
                                    <span className="font-semibold text-on-surface">{tier.maxBorrowBooks} quyß╗ân</span>
                                </div>
                                <div className="flex justify-between">
                                    <span className="text-on-surface-variant">Ng├áy m╞░ß╗ún tß╗æi ─æa:</span>
                                    <span className="font-semibold text-on-surface">{tier.maxBorrowDays} ng├áy</span>
                                </div>
                            </div>
                        </div>
                    ))}
                    {tiers.length === 0 && (
                        <div className="col-span-full flex flex-col items-center justify-center rounded-xl border border-dashed border-outline-variant p-12 text-on-surface-variant">
                            <Shield size={48} className="mb-4 opacity-50" />
                            <p>Ch╞░a c├│ hß║íng th├ánh vi├¬n n├áo ─æ╞░ß╗úc thiß║┐t lß║¡p.</p>
                        </div>
                    )}
                </div>
            )}

            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 px-4 backdrop-blur-sm">
                    <div className="w-full max-w-md rounded-2xl bg-surface p-6 shadow-xl">
                        <h2 className="mb-6 text-xl font-bold">{editingTier ? "Sß╗¡a Hß║íng th├ánh vi├¬n" : "Th├¬m Hß║íng th├ánh vi├¬n"}</h2>
                        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
                            <div>
                                <label className="mb-1 block text-sm font-medium">T├¬n hß║íng (Vd: V├áng, Bß║íc) *</label>
                                <input
                                    required
                                    className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                    value={form.name}
                                    onChange={(e) => setForm({ ...form, name: e.target.value })}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="mb-1 block text-sm font-medium">─Éiß╗âm tß╗æi thiß╗âu *</label>
                                    <input
                                        required
                                        type="number"
                                        min="0"
                                        className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                        value={form.minPoints}
                                        onChange={(e) => setForm({ ...form, minPoints: Number(e.target.value) })}
                                    />
                                </div>
                                <div>
                                    <label className="mb-1 block text-sm font-medium">Giß║úm gi├í (%) *</label>
                                    <input
                                        required
                                        type="number"
                                        min="0"
                                        max="100"
                                        className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                        value={form.discountPercent}
                                        onChange={(e) => setForm({ ...form, discountPercent: Number(e.target.value) })}
                                    />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="mb-1 block text-sm font-medium">Sß╗æ ng├áy m╞░ß╗ún tß╗æi ─æa *</label>
                                    <input
                                        required
                                        type="number"
                                        min="1"
                                        className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                        value={form.maxBorrowDays}
                                        onChange={(e) => setForm({ ...form, maxBorrowDays: Number(e.target.value) })}
                                    />
                                </div>
                                <div>
                                    <label className="mb-1 block text-sm font-medium">Sß╗æ s├ích tß╗æi ─æa *</label>
                                    <input
                                        required
                                        type="number"
                                        min="1"
                                        className="w-full rounded-lg border border-outline-variant bg-surface-container-low p-2.5"
                                        value={form.maxBorrowBooks}
                                        onChange={(e) => setForm({ ...form, maxBorrowBooks: Number(e.target.value) })}
                                    />
                                </div>
                            </div>
                            
                            <div className="mt-6 flex justify-end gap-3 border-t border-outline-variant/30 pt-4">
                                <button type="button" onClick={handleCloseModal} className="rounded-lg px-4 py-2 text-sm font-medium hover:bg-surface-variant">Hß╗ºy</button>
                                <button type="submit" className="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-white hover:bg-primary/90">L╞░u th├┤ng tin</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Search, RotateCcw, AlertCircle, CheckCircle2, SearchX } from "lucide-react";
import { toast } from "sonner";
import { formatCurrency, formatDate } from "@/lib/utils";
import { AdminPayment, getAdminPayments, refundAdminPayment } from "@/services/adminPayment";

export default function PaymentManagement() {
    const [payments, setPayments] = useState<AdminPayment[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isRefunding, setIsRefunding] = useState<number | null>(null);
    
    // Pagination & Search
    const [page, setPage] = useState(0);
    const [totalPages, setTotalPages] = useState(1);
    const [searchCode, setSearchCode] = useState("");
    const [activeSearch, setActiveSearch] = useState("");

    useEffect(() => {
        fetchPayments();
    }, [page, activeSearch]);

    const fetchPayments = async () => {
        setIsLoading(true);
        try {
            const res = await getAdminPayments(page, 15, activeSearch);
            if (res.success && res.data) {
                setPayments(res.data.content);
                setTotalPages(res.data.totalPages);
            }
        } catch (error) {
            toast.error("Kh├┤ng thß╗â tß║úi danh s├ích giao dß╗ïch");
        } finally {
            setIsLoading(false);
        }
    };

    const handleSearch = () => {
        setPage(0);
        setActiveSearch(searchCode);
    };

    const handleRefund = async (id: number) => {
        if (!confirm("X├íc nhß║¡n ho├án tiß╗ün cho giao dß╗ïch n├áy?")) return;
        
        setIsRefunding(id);
        try {
            const res = await refundAdminPayment(id);
            if (res.success) {
                toast.success("─É├ú ho├án tiß╗ün th├ánh c├┤ng!");
                fetchPayments();
            } else {
                toast.error(res.message || "Ho├án tiß╗ün thß║Ñt bß║íi");
            }
        } catch (error) {
            toast.error("Lß╗ùi kß║┐t nß╗æi");
        } finally {
            setIsRefunding(null);
        }
    };

    const getStatusBadge = (status: string) => {
        switch (status) {
            case "PAID": return <span className="rounded bg-success/10 px-2 py-1 text-xs font-semibold text-success">─É├ú thanh to├ín</span>;
            case "REFUNDED": return <span className="rounded bg-primary/10 px-2 py-1 text-xs font-semibold text-primary">─É├ú ho├án tiß╗ün</span>;
            case "PENDING": return <span className="rounded bg-warning/10 px-2 py-1 text-xs font-semibold text-warning">─Éang chß╗¥ xß╗¡ l├╜</span>;
            case "FAILED": return <span className="rounded bg-error/10 px-2 py-1 text-xs font-semibold text-error">Thß║Ñt bß║íi</span>;
            default: return <span className="rounded bg-surface-variant px-2 py-1 text-xs font-semibold">{status}</span>;
        }
    };

    return (
        <div className="flex h-full flex-col p-6">
            <div className="mb-6 flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-on-surface">─Éß╗æi so├ít thanh to├ín</h1>
                    <p className="text-sm text-on-surface-variant">Lß╗ïch sß╗¡ giao dß╗ïch VNPay v├á quß║ún l├╜ ho├án tiß╗ün</p>
                </div>
                <div className="flex gap-2">
                    <input
                        type="text"
                        placeholder="M├ú giao dß╗ïch..."
                        className="rounded-lg border border-outline-variant bg-surface-container-low px-4 py-2 text-sm"
                        value={searchCode}
                        onChange={(e) => setSearchCode(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                    />
                    <button onClick={handleSearch} className="flex items-center gap-2 rounded-lg bg-surface-variant px-4 py-2 text-sm font-medium hover:bg-outline-variant/30">
                        <Search size={18} /> T├¼m
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-hidden rounded-xl border border-outline-variant/30 bg-surface shadow-sm flex flex-col">
                <div className="overflow-x-auto flex-1">
                    <table className="w-full text-left text-sm">
                        <thead className="sticky top-0 bg-surface-container-low">
                            <tr>
                                <th className="p-4 font-semibold">M├ú GD (VNPay)</th>
                                <th className="p-4 font-semibold">M├ú ─É╞ín m╞░ß╗ún</th>
                                <th className="p-4 font-semibold">Loß║íi</th>
                                <th className="p-4 font-semibold text-right">Sß╗æ tiß╗ün</th>
                                <th className="p-4 font-semibold text-center">Trß║íng th├íi</th>
                                <th className="p-4 font-semibold">Ng├áy giao dß╗ïch</th>
                                <th className="p-4 font-semibold">Ng╞░ß╗¥i xß╗¡ l├╜</th>
                                <th className="p-4 font-semibold text-center">Thao t├íc</th>
                            </tr>
                        </thead>
                        <tbody>
                            {isLoading ? (
                                <tr>
                                    <td colSpan={8} className="p-12 text-center">
                                        <div className="mx-auto h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
                                    </td>
                                </tr>
                            ) : payments.length === 0 ? (
                                <tr>
                                    <td colSpan={8} className="p-12 text-center text-on-surface-variant">
                                        <SearchX size={32} className="mx-auto mb-2 opacity-50" />
                                        Kh├┤ng t├¼m thß║Ñy giao dß╗ïch n├áo
                                    </td>
                                </tr>
                            ) : (
                                payments.map((payment) => (
                                    <tr key={payment.id} className="border-b border-outline-variant/20 hover:bg-surface-variant/30 transition-colors">
                                        <td className="p-4 font-medium text-primary">{payment.transactionCode || "N/A"}</td>
                                        <td className="p-4">{payment.orderCode || "N/A"}</td>
                                        <td className="p-4">
                                            {payment.paymentType === "DEPOSIT" ? "Tiß╗ün cß╗ìc" : payment.paymentType === "FINE" ? "Tiß╗ün phß║ít" : payment.paymentType}
                                        </td>
                                        <td className="p-4 text-right font-semibold text-error">{formatCurrency(payment.amount)}</td>
                                        <td className="p-4 text-center">{getStatusBadge(payment.paymentStatus)}</td>
                                        <td className="p-4 text-xs">{payment.paymentDate ? formatDate(payment.paymentDate) : "N/A"}</td>
                                        <td className="p-4 text-on-surface-variant">{payment.processedByName || "-"}</td>
                                        <td className="p-4 text-center">
                                            {payment.paymentStatus === "PAID" && payment.paymentType === "DEPOSIT" && (
                                                <button
                                                    onClick={() => handleRefund(payment.id)}
                                                    disabled={isRefunding === payment.id}
                                                    className="inline-flex items-center gap-1 rounded bg-surface-variant px-3 py-1.5 text-xs font-medium text-on-surface hover:bg-outline-variant/30 disabled:opacity-50"
                                                    title="Ho├án trß║ú tiß╗ün cß╗ìc cho kh├ích"
                                                >
                                                    {isRefunding === payment.id ? (
                                                        <div className="h-3 w-3 animate-spin rounded-full border-2 border-primary border-t-transparent"></div>
                                                    ) : (
                                                        <RotateCcw size={14} />
                                                    )}
                                                    Ho├án tiß╗ün
                                                </button>
                                            )}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
                
                {/* Pagination */}
                {totalPages > 1 && (
                    <div className="flex items-center justify-between border-t border-outline-variant/30 bg-surface px-6 py-4">
                        <span className="text-sm text-on-surface-variant">Trang {page + 1} / {totalPages}</span>
                        <div className="flex gap-2">
                            <button
                                disabled={page === 0}
                                onClick={() => setPage(page - 1)}
                                className="rounded border border-outline-variant px-3 py-1 text-sm disabled:opacity-50"
                            >
                                Tr╞░ß╗¢c
                            </button>
                            <button
                                disabled={page >= totalPages - 1}
                                onClick={() => setPage(page + 1)}
                                className="rounded border border-outline-variant px-3 py-1 text-sm disabled:opacity-50"
                            >
                                Sau
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

