"use client";

import { useEffect, useState } from "react";
import { Search, Monitor, Smartphone, Globe, LogOut, ShieldAlert } from "lucide-react";
import { toast } from "sonner";
import { formatDate } from "@/lib/utils";
import { AdminSession, getAllSessions, terminateSession, terminateAllUserSessions } from "@/services/adminSession";

export default function SessionManagement() {
    const [sessions, setSessions] = useState<AdminSession[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchKeyword, setSearchKeyword] = useState("");

    useEffect(() => {
        fetchSessions();
    }, []);

    const fetchSessions = async () => {
        setIsLoading(true);
        try {
            const res = await getAllSessions();
            if (res.success && res.data) {
                setSessions(res.data);
            }
        } catch (error) {
            toast.error("Kh├┤ng thß╗â tß║úi danh s├ích phi├¬n ─æ─âng nhß║¡p");
        } finally {
            setIsLoading(false);
        }
    };

    const handleTerminate = async (sessionId: string) => {
        if (!confirm("X├íc nhß║¡n ─æ─âng xuß║Ñt phi├¬n thiß║┐t bß╗ï n├áy?")) return;
        
        try {
            const res = await terminateSession(sessionId);
            if (res.success) {
                toast.success("─É├ú ─æ─âng xuß║Ñt thiß║┐t bß╗ï th├ánh c├┤ng!");
                fetchSessions();
            } else {
                toast.error(res.message || "─É─âng xuß║Ñt thß║Ñt bß║íi");
            }
        } catch (error) {
            toast.error("Lß╗ùi kß║┐t nß╗æi");
        }
    };

    const handleTerminateAll = async (userId: number) => {
        if (!confirm("X├íc nhß║¡n ─æ─âng xuß║Ñt TO├ÇN Bß╗ÿ thiß║┐t bß╗ï cß╗ºa ng╞░ß╗¥i d├╣ng n├áy?")) return;
        
        try {
            const res = await terminateAllUserSessions(userId);
            if (res.success) {
                toast.success("─É├ú ─æ─âng xuß║Ñt tß║Ñt cß║ú thiß║┐t bß╗ï th├ánh c├┤ng!");
                fetchSessions();
            } else {
                toast.error(res.message || "─É─âng xuß║Ñt thß║Ñt bß║íi");
            }
        } catch (error) {
            toast.error("Lß╗ùi kß║┐t nß╗æi");
        }
    };

    const getDeviceIcon = (userAgent: string) => {
        const ua = userAgent.toLowerCase();
        if (ua.includes("mobile") || ua.includes("android") || ua.includes("iphone")) return <Smartphone size={20} className="text-primary" />;
        return <Monitor size={20} className="text-primary" />;
    };

    const getBrowserInfo = (userAgent: string) => {
        const ua = userAgent.toLowerCase();
        if (ua.includes("chrome")) return "Chrome";
        if (ua.includes("firefox")) return "Firefox";
        if (ua.includes("safari") && !ua.includes("chrome")) return "Safari";
        if (ua.includes("edge")) return "Edge";
        return "Unknown Browser";
    };

    const filteredSessions = sessions.filter(s => 
        s.username?.toLowerCase().includes(searchKeyword.toLowerCase()) || 
        s.fullName?.toLowerCase().includes(searchKeyword.toLowerCase()) ||
        s.ipAddress?.includes(searchKeyword)
    );

    return (
        <div className="flex h-full flex-col p-6">
            <div className="mb-6 flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-on-surface">Quß║ún l├╜ phi├¬n ─æ─âng nhß║¡p</h1>
                    <p className="text-sm text-on-surface-variant">Kiß╗âm so├ít c├íc thiß║┐t bß╗ï ─æang hoß║ít ─æß╗Öng tr├¬n hß╗ç thß╗æng</p>
                </div>
                <div className="flex gap-2">
                    <input
                        type="text"
                        placeholder="T├¼m email, t├¬n, IP..."
                        className="rounded-lg border border-outline-variant bg-surface-container-low px-4 py-2 text-sm"
                        value={searchKeyword}
                        onChange={(e) => setSearchKeyword(e.target.value)}
                    />
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 overflow-y-auto pb-12">
                {isLoading ? (
                    <div className="col-span-full py-12 flex justify-center">
                        <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
                    </div>
                ) : filteredSessions.length === 0 ? (
                    <div className="col-span-full py-12 text-center text-on-surface-variant bg-surface rounded-xl border border-outline-variant/30">
                        <ShieldAlert size={48} className="mx-auto mb-4 opacity-50" />
                        <p>Kh├┤ng c├│ phi├¬n ─æ─âng nhß║¡p n├áo ─æang hoß║ít ─æß╗Öng</p>
                    </div>
                ) : (
                    filteredSessions.map((session) => (
                        <div key={session.id} className="rounded-xl border border-outline-variant/30 bg-surface p-4 shadow-sm relative overflow-hidden flex flex-col gap-4">
                            <div className="absolute top-0 right-0 h-1 w-full bg-success"></div>
                            
                            <div className="flex justify-between items-start">
                                <div className="flex items-center gap-3">
                                    <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                                        {getDeviceIcon(session.userAgent)}
                                    </div>
                                    <div>
                                        <h3 className="font-semibold text-on-surface line-clamp-1">{session.fullName || session.username}</h3>
                                        <p className="text-xs text-on-surface-variant">{session.username}</p>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => handleTerminateAll(session.userId)}
                                    className="text-[10px] bg-error/10 text-error px-2 py-1 rounded font-medium hover:bg-error hover:text-white transition-colors"
                                    title="─É─âng xuß║Ñt khß╗Åi tß║Ñt cß║ú thiß║┐t bß╗ï"
                                >
                                    ─É─âng xuß║Ñt tß║Ñt cß║ú
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-2 text-sm">
                                <div className="flex items-center gap-2 text-on-surface-variant">
                                    <Globe size={14} /> <span>IP: {session.ipAddress === "0:0:0:0:0:0:0:1" ? "127.0.0.1" : session.ipAddress}</span>
                                </div>
                                <div className="text-on-surface-variant text-right">
                                    {getBrowserInfo(session.userAgent)}
                                </div>
                                <div className="col-span-2 text-xs text-on-surface-variant mt-1">
                                    ─É─âng nhß║¡p: {session.loginTime ? formatDate(session.loginTime) : "Gß║ºn ─æ├óy"}
                                </div>
                            </div>

                            <button 
                                onClick={() => handleTerminate(session.id)}
                                className="mt-auto flex w-full items-center justify-center gap-2 rounded-lg bg-surface-variant py-2 text-sm font-medium text-error hover:bg-error/10 transition-colors border border-transparent hover:border-error/20"
                            >
                                <LogOut size={16} /> Ngß║»t kß║┐t nß╗æi thiß║┐t bß╗ï n├áy
                            </button>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { toast } from "sonner";
import { MaterialIcon } from "@/components/base/material-icon";
import { UI_TEXT } from "@/constants/ui-text";
import { createSupportRequest } from "@/services/support";

const contactSchema = z.object({
  name: z.string().min(1, "Vui l├▓ng nhß║¡p hß╗ì v├á t├¬n"),
  email: z.string().email("Email kh├┤ng hß╗úp lß╗ç"),
  subject: z.string().min(1, "Vui l├▓ng chß╗ìn chß╗º ─æß╗ü"),
  message: z.string().min(10, "Nß╗Öi dung tß╗æi thiß╗âu 10 k├╜ tß╗▒"),
});

type ContactFormValues = z.infer<typeof contactSchema>;

const FAQ_ITEMS = [
  {
    id: "faq-ai-search",
    question: UI_TEXT.CONTACT.FAQS[0].QUESTION,
    answer: UI_TEXT.CONTACT.FAQS[0].ANSWER,
  },
  {
    id: "faq-api-access",
    question: UI_TEXT.CONTACT.FAQS[1].QUESTION,
    answer: UI_TEXT.CONTACT.FAQS[1].ANSWER,
  },
  {
    id: "faq-library-hours",
    question: UI_TEXT.CONTACT.FAQS[2].QUESTION,
    answer: UI_TEXT.CONTACT.FAQS[2].ANSWER,
  },
];

export default function ContactContent() {
  const [activeAccordion, setActiveAccordion] = useState<string | null>(null);

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<ContactFormValues>({
    resolver: zodResolver(contactSchema),
    defaultValues: {
      name: "",
      email: "",
      subject: "",
      message: "",
    },
  });

  const onSubmit = async (data: ContactFormValues) => {
    try {
      const res = await createSupportRequest(data);
      if (res.success) {
        toast.success(res.message || "Y├¬u cß║ºu ─æ├ú ─æ╞░ß╗úc gß╗¡i th├ánh c├┤ng");
        reset();
      } else {
        toast.error(res.message || "C├│ lß╗ùi xß║úy ra, vui l├▓ng thß╗¡ lß║íi sau");
      }
    } catch (error: any) {
      toast.error(error.response?.data?.message || "C├│ lß╗ùi xß║úy ra, vui l├▓ng thß╗¡ lß║íi sau");
    }
  };

  const toggleAccordion = (id: string) => {
    setActiveAccordion((prev) => (prev === id ? null : id));
  };

  return (
    <main className="mx-auto w-full max-w-[1440px] flex-grow space-y-12 px-4 py-12 md:px-6">
      {/* Header Section */}
      <header className="mx-auto mb-12 max-w-3xl space-y-4 text-center">
        <h1 className="text-5xl font-bold leading-[56px] tracking-[-0.02em] text-primary dark:text-white transition-colors duration-200">
          {UI_TEXT.CONTACT.HEADING}
        </h1>
        <p className="text-base leading-6 text-on-surface-variant dark:text-white transition-colors duration-200">
          {UI_TEXT.CONTACT.SUBHEADING}
        </p>
      </header>

      {/* Bento Grid Layout for Contact & Details */}
      <div className="grid grid-cols-1 items-start gap-6 lg:grid-cols-12">
        {/* Contact Form Area (Main Focus) */}
        <section className="rounded-xl border border-surface-variant dark:border-slate-800 bg-surface-container-lowest dark:bg-slate-900 p-6 shadow-[0_4px_12px_rgba(0,0,0,0.05)] md:p-12 lg:col-span-7 xl:col-span-8 transition-colors duration-200">
          <h2 className="mb-6 flex items-center gap-2 text-xl font-semibold leading-7 text-primary dark:text-white transition-colors duration-200">
            <MaterialIcon name="mail" className="text-secondary dark:text-white" />
            {UI_TEXT.CONTACT.FORM_HEADING}
          </h2>
          <form className="space-y-4" onSubmit={handleSubmit(onSubmit)}>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
              <div className="space-y-1">
                <label
                  className="font-mono text-xs font-medium uppercase leading-4 tracking-[0.05em] text-on-surface-variant dark:text-white transition-colors duration-200"
                  htmlFor="contact-name"
                >
                  {UI_TEXT.CONTACT.NAME_LABEL}
                </label>
                <input
                  className={`w-full rounded-lg border-none bg-background dark:bg-slate-800 p-4 text-base leading-6 text-on-surface dark:text-white transition-all focus:ring-1 focus:ring-primary dark:focus:ring-white ${errors.name ? 'ring-1 ring-error focus:ring-error' : ''}`}
                  id="contact-name"
                  placeholder={UI_TEXT.CONTACT.NAME_PLACEHOLDER}
                  type="text"
                  {...register("name")}
                />
                {errors.name && <p className="text-xs text-error mt-1">{errors.name.message}</p>}
              </div>
              <div className="space-y-1">
                <label
                  className="font-mono text-xs font-medium uppercase leading-4 tracking-[0.05em] text-on-surface-variant dark:text-white transition-colors duration-200"
                  htmlFor="contact-email"
                >
                  {UI_TEXT.CONTACT.EMAIL_LABEL}
                </label>
                <input
                  className={`w-full rounded-lg border-none bg-background dark:bg-slate-800 p-4 text-base leading-6 text-on-surface dark:text-white transition-all focus:ring-1 focus:ring-primary dark:focus:ring-white ${errors.email ? 'ring-1 ring-error focus:ring-error' : ''}`}
                  id="contact-email"
                  placeholder="email@example.com"
                  type="email"
                  {...register("email")}
                />
                {errors.email && <p className="text-xs text-error mt-1">{errors.email.message}</p>}
              </div>
            </div>
            <div className="space-y-1">
              <label
                className="font-mono text-xs font-medium uppercase leading-4 tracking-[0.05em] text-on-surface-variant dark:text-white transition-colors duration-200"
                htmlFor="contact-subject"
              >
                {UI_TEXT.CONTACT.SUBJECT_LABEL}
              </label>
              <select
                className={`w-full rounded-lg border-none bg-background dark:bg-slate-800 p-4 text-base leading-6 text-on-surface dark:text-white transition-all focus:ring-1 focus:ring-primary dark:focus:ring-white ${errors.subject ? 'ring-1 ring-error focus:ring-error' : ''}`}
                id="contact-subject"
                {...register("subject")}
              >
                <option value="">{UI_TEXT.CONTACT.SUBJECT_OPTIONS.DEFAULT}</option>
                <option value="access">{UI_TEXT.CONTACT.SUBJECT_OPTIONS.ACCESS}</option>
                <option value="support">{UI_TEXT.CONTACT.SUBJECT_OPTIONS.TECH_SUPPORT}</option>
                <option value="collection">{UI_TEXT.CONTACT.SUBJECT_OPTIONS.COLLECTION}</option>
                <option value="other">{UI_TEXT.CONTACT.SUBJECT_OPTIONS.OTHER}</option>
              </select>
              {errors.subject && <p className="text-xs text-error mt-1">{errors.subject.message}</p>}
            </div>
            <div className="space-y-1">
              <label
                className="font-mono text-xs font-medium uppercase leading-4 tracking-[0.05em] text-on-surface-variant dark:text-white transition-colors duration-200"
                htmlFor="contact-message"
              >
                {UI_TEXT.CONTACT.MESSAGE_LABEL}
              </label>
              <textarea
                className={`w-full resize-none rounded-lg border-none bg-background dark:bg-slate-800 p-4 text-base leading-6 text-on-surface dark:text-white transition-all focus:ring-1 focus:ring-primary dark:focus:ring-white ${errors.message ? 'ring-1 ring-error focus:ring-error' : ''}`}
                id="contact-message"
                placeholder={UI_TEXT.CONTACT.MESSAGE_PLACEHOLDER}
                rows={5}
                {...register("message")}
              />
              {errors.message && <p className="text-xs text-error mt-1">{errors.message.message}</p>}
            </div>
            <div className="pt-2">
              <button
                className="inline-flex w-full items-center justify-center gap-2 rounded-full bg-primary px-12 py-4 text-xl font-semibold leading-7 text-on-primary shadow-[0_4px_12px_rgba(0,0,0,0.05)] transition-all hover:bg-primary-container hover:shadow-[0_12px_32px_rgba(0,0,0,0.1)] md:w-auto disabled:opacity-70 disabled:cursor-not-allowed"
                type="submit"
                disabled={isSubmitting}
              >
                {isSubmitting ? "─Éang gß╗¡i..." : UI_TEXT.CONTACT.SUBMIT_BTN}
                {!isSubmitting && <MaterialIcon name="send" className="text-sm" />}
              </button>
            </div>
          </form>
        </section>

        {/* Sidebar: Details & Map */}
        <aside className="flex h-full flex-col space-y-6 lg:col-span-5 xl:col-span-4">
          {/* Contact Information Card */}
          <div className="flex-grow rounded-xl border border-outline-variant/30 dark:border-slate-800 bg-surface-container-low dark:bg-slate-900 p-6 space-y-4 transition-colors duration-200">
            <h3 className="border-b border-outline-variant/30 dark:border-slate-800 pb-2 text-xl font-semibold leading-7 text-primary dark:text-white transition-colors duration-200">
              {UI_TEXT.CONTACT.INFO_HEADING}
            </h3>
            <ul className="space-y-4 pt-2">
              <li className="group flex items-start gap-4">
                <div className="rounded-full bg-surface-container-highest dark:bg-slate-800 p-2 text-secondary dark:text-white transition-colors group-hover:bg-secondary-container dark:group-hover:bg-secondary-500/20">
                  <MaterialIcon name="location_on" />
                </div>
                <div>
                  <p className="mb-1 font-mono text-xs font-medium uppercase leading-4 tracking-[0.05em] text-on-surface-variant dark:text-white transition-colors duration-200">
                    {UI_TEXT.CONTACT.ADDRESS_LABEL}
                  </p>
                  <p className="text-base font-medium leading-6 text-on-surface dark:text-white transition-colors duration-200">
                    {UI_TEXT.CONTACT.ADDRESS_LINE_1}
                    <br />
                    {UI_TEXT.CONTACT.ADDRESS_LINE_2}
                    <br />
                    {UI_TEXT.CONTACT.ADDRESS_LINE_3}
                  </p>
                </div>
              </li>
              <li className="group flex items-start gap-4">
                <div className="rounded-full bg-surface-container-highest dark:bg-slate-800 p-2 text-secondary dark:text-white transition-colors group-hover:bg-secondary-container dark:group-hover:bg-secondary-500/20">
                  <MaterialIcon name="phone" />
                </div>
                <div>
                  <p className="mb-1 font-mono text-xs font-medium uppercase leading-4 tracking-[0.05em] text-on-surface-variant dark:text-white transition-colors duration-200">
                    {UI_TEXT.CONTACT.SUPPORT_LABEL}
                  </p>
                  <p className="text-base font-medium leading-6 text-on-surface dark:text-white transition-colors duration-200">
                    {UI_TEXT.CONTACT.PHONE}
                  </p>
                </div>
              </li>
              <li className="group flex items-start gap-4">
                <div className="rounded-full bg-surface-container-highest dark:bg-slate-800 p-2 text-secondary dark:text-white transition-colors group-hover:bg-secondary-container dark:group-hover:bg-secondary-500/20">
                  <MaterialIcon name="alternate_email" />
                </div>
                <div>
                  <p className="mb-1 font-mono text-xs font-medium uppercase leading-4 tracking-[0.05em] text-on-surface-variant dark:text-white transition-colors duration-200">
                    {UI_TEXT.CONTACT.INFO_EMAIL_LABEL}
                  </p>
                  <p className="text-base font-medium leading-6 text-on-surface dark:text-white transition-colors duration-200">
                    {UI_TEXT.CONTACT.EMAIL}
                  </p>
                </div>
              </li>
            </ul>
          </div>

          {/* Map Component (Visual anchor) */}
          <div className="map-container relative h-64 w-full overflow-hidden rounded-xl border border-outline-variant/30 dark:border-slate-800 bg-surface-variant dark:bg-slate-900 transition-colors duration-200">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              className="h-full w-full object-cover dark:opacity-70 transition-opacity"
              src="https://lh3.googleusercontent.com/aida-public/AB6AXuCYrrGABKWhsjlUQauZaA0B8xhhhlC-of7fsx3WYu8Qwpd6TCoS4Mp5bTfyGg96hI4woPHNS6KFIUC9Uiz7tSapcmFiuiydfU2Ytv2-L8vpshtr9sII7xxlGIQmFnsajRRfe6Om53yyXzgdKb2ofWqUIwhrmjbbrmVe8jzRo8SDX73ZkrTqLrrDF2JxINNA3qATvpnyPYE_Jq76Ywo0Wub_e8dXXti2Mp6ZEXv4AK01jU5quZmX3DS55IL9AzVxlfRBrfEIx4wMTN7L"
              alt={UI_TEXT.CONTACT.MAP_ALT}
            />
            <div className="map-overlay pointer-events-none absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-background/90 dark:to-slate-950/90 transition-colors duration-200" />
            <div className="absolute bottom-4 left-4 right-4">
              <button
                className="flex w-full items-center justify-center gap-1 rounded-lg border border-outline-variant/30 dark:border-slate-700 bg-surface-container-lowest/90 dark:bg-slate-800/90 px-4 py-2 text-xl font-semibold leading-7 text-primary dark:text-white shadow-sm backdrop-blur-sm transition-colors hover:bg-surface-container-lowest dark:hover:bg-slate-800"
                type="button"
              >
                <MaterialIcon name="directions" className="text-sm" />
                {UI_TEXT.CONTACT.DIRECTIONS_BTN}
              </button>
            </div>
          </div>
        </aside>
      </div>

      {/* FAQ Section */}
      <section className="mx-auto max-w-4xl pt-12">
        <div className="mb-6 text-center">
          <h2 className="text-[32px] font-semibold leading-10 tracking-[-0.01em] text-primary dark:text-white transition-colors duration-200">
            {UI_TEXT.CONTACT.FAQ_HEADING}
          </h2>
          <p className="mt-2 text-base leading-6 text-on-surface-variant dark:text-white transition-colors duration-200">
            {UI_TEXT.CONTACT.FAQ_SUBHEADING}
          </p>
        </div>
        <div className="space-y-2">
          {FAQ_ITEMS.map((item) => (
            <div
              key={item.id}
              className="overflow-hidden rounded-lg border border-surface-variant dark:border-slate-800 bg-surface-container-lowest dark:bg-slate-900 transition-colors duration-200"
            >
              <button
                className="flex w-full items-center justify-between px-6 py-4 text-left transition-colors hover:bg-surface-container-low dark:hover:bg-slate-800/50"
                onClick={() => toggleAccordion(item.id)}
                type="button"
                aria-expanded={activeAccordion === item.id}
                aria-controls={`${item.id}-content`}
              >
                <span className="text-xl font-semibold leading-7 text-on-surface dark:text-white transition-colors duration-200">
                  {item.question}
                </span>
                <MaterialIcon
                  name="expand_more"
                  className={`text-secondary dark:text-white transition-transform duration-300 ${
                    activeAccordion === item.id ? "rotate-180" : ""
                  }`}
                />
              </button>
              <div
                id={`${item.id}-content`}
                className={`overflow-hidden transition-all duration-300 ease-out ${
                  activeAccordion === item.id
                    ? "max-h-[500px] opacity-100"
                    : "max-h-0 opacity-0"
                }`}
                role="region"
                aria-labelledby={item.id}
              >
                <div className="border-t border-surface-variant dark:border-slate-800 bg-background dark:bg-slate-950 px-6 pb-4 pt-2 text-base leading-6 text-on-surface-variant dark:text-white transition-colors duration-200">
                  {item.answer}
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>
    </main>
  );
}

"use client";
import { QRCodeSVG } from "qrcode.react";
import { useAuth } from "@/providers/auth";
import { MaterialIcon } from "@/components/base/material-icon";
import { BaseButton } from "@/components/base/base-button";

export default function LibraryCard() {
    const { user } = useAuth();
    if (!user) return null;

    // Simulate a library card number based on user ID or email
    const cardNumber = `LIB-${new Date().getFullYear()}-${user.id ? user.id.toString().padStart(5, '0') : "00000"}`;

    const handleDownload = () => {
        const svg = document.getElementById("library-card-qr");
        if (svg) {
            const svgData = new XMLSerializer().serializeToString(svg);
            const canvas = document.createElement("canvas");
            const ctx = canvas.getContext("2d");
            const img = new Image();
            img.onload = () => {
                canvas.width = img.width;
                canvas.height = img.height;
                if (ctx) {
                    ctx.drawImage(img, 0, 0);
                    const pngFile = canvas.toDataURL("image/png");
                    const downloadLink = document.createElement("a");
                    downloadLink.download = `LibraryCard_${cardNumber}.png`;
                    downloadLink.href = `${pngFile}`;
                    downloadLink.click();
                }
            };
            img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
        }
    };

    return (
        <div className="mt-8 rounded-xl border border-outline-variant/30 bg-surface-container-low p-6 shadow-sm dark:border-slate-800 dark:bg-slate-900 md:p-8">
