                Thß║╗ th╞░ viß╗çn ─æiß╗çn tß╗¡
            </h2>
            <div className="flex flex-col items-center justify-between gap-8 md:flex-row">
                <div className="flex-1 space-y-4 text-center md:text-left">
                    <p className="text-body-md text-on-surface-variant dark:text-slate-400">
                        Sß╗¡ dß╗Ñng m├ú QR n├áy ─æß╗â qu├⌐t nhanh khi ─æß║┐n m╞░ß╗ún/trß║ú s├ích tß║íi quß║ºy th╞░ viß╗çn Lumina.
                    </p>
                    <div className="space-y-1">
                        <p className="font-mono text-sm uppercase tracking-wider text-outline dark:text-slate-500">M├ú thß║╗</p>
                        <p className="text-xl font-bold text-on-surface dark:text-white">{cardNumber}</p>
                    </div>
                    <div className="space-y-1">
                        <p className="font-mono text-sm uppercase tracking-wider text-outline dark:text-slate-500">Hß╗ì v├á t├¬n</p>
                        <p className="text-lg font-medium text-on-surface dark:text-white">{user.fullName}</p>
                    </div>
                    <div className="pt-4">
                        <BaseButton onClick={handleDownload} variant="outline" className="w-full md:w-auto dark:border-slate-700 dark:text-white">
                            <MaterialIcon name="download" className="mr-2 text-sm" />
                            Tß║úi m├ú QR
                        </BaseButton>
                    </div>
                </div>
                <div className="flex flex-shrink-0 flex-col items-center justify-center rounded-2xl bg-white p-6 shadow-sm border border-gray-100">
                    <QRCodeSVG
                        id="library-card-qr"
                        value={cardNumber}
                        size={160}
                        bgColor={"#ffffff"}
                        fgColor={"#0f172a"}
                        level={"H"}
                        includeMargin={false}
                    />
                    <p className="mt-3 text-xs text-gray-500">Lumina Library</p>
                </div>
            </div>
        </div>
    );
}
